import{_ as s,o as t,c as e,a5 as i}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"网络案例：请求超时与延迟","description":"案例说明： 本页日期、业务背景、指标和工具输出均为构造或匿名化教学数据；除引用一手资料外，不应视为可核验的真实事件。排查方法与命令仍需结合目标 JDK、系统和生产变更流程验证。","frontmatter":{},"headers":[],"relativePath":"java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md","filePath":"java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"}'),n={name:"java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"};function c(l,a,r,d,h,o){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="网络案例-请求超时与延迟" tabindex="-1" data-src-line="1" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">网络案例：请求超时与延迟 <a class="header-anchor" href="#网络案例-请求超时与延迟" aria-label="Permalink to &quot;网络案例：请求超时与延迟&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"><p data-src-line="3" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"><strong>案例说明：</strong> 本页日期、业务背景、指标和工具输出均为构造或匿名化教学数据；除引用一手资料外，不应视为可核验的真实事件。排查方法与命令仍需结合目标 JDK、系统和生产变更流程验证。</p></blockquote><p data-src-line="5" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">这组案例关注「请求发出去了但很久才回来」或「直接超时」。超时既可能是网络问题，也可能是对端处理慢、应用消费不及时或下游依赖变慢。难点是把「耗时花在哪一段」拆清楚，而不是把超时直接等同于网络故障。</p><h2 id="case-1" tabindex="-1" data-src-line="7" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">案例一：read timed out 指向对端处理慢 <a class="header-anchor" href="#case-1" aria-label="Permalink to &quot;案例一：read timed out 指向对端处理慢 {#case-1}&quot;">​</a></h2><h3 id="_1-1-事故背景" tabindex="-1" data-src-line="9" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">1.1 事故背景 <a class="header-anchor" href="#_1-1-事故背景" aria-label="Permalink to &quot;1.1 事故背景&quot;">​</a></h3><p data-src-line="11" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">某订单服务调用风控服务，白天偶发 <code>SocketTimeoutException: Read timed out</code>，超时设 3 秒。网络组坚持网络没问题，因为 ping 正常、带宽空闲。</p><h3 id="_1-2-第一步-拆连接阶段和读阶段" tabindex="-1" data-src-line="13" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">1.2 第一步：拆连接阶段和读阶段 <a class="header-anchor" href="#_1-2-第一步-拆连接阶段和读阶段" aria-label="Permalink to &quot;1.2 第一步：拆连接阶段和读阶段&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 服务端抓该连接的请求/响应时序</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> risk-svc.internal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/risk.pcap</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10:05:00.000  client → server: [P.] 请求数据</span></span>
<span class="line"><span>10:05:00.001  server → client: [.]   ACK（确认收到请求）</span></span>
<span class="line"><span>10:05:02.800  server → client: [P.] 响应数据      ← 请求到响应差 2.8 秒</span></span>
<span class="line"><span>10:05:02.801  client → server: [.]   ACK</span></span></code></pre></div><p data-src-line="27" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">握手很快，请求被 ACK 也很快，但从请求到响应之间的 2.8 秒全在对端处理上。ping 正常只能说明网络层可达，不能说明应用层快。</p><h3 id="_1-3-第二步-回服务端查处理耗时" tabindex="-1" data-src-line="29" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">1.3 第二步：回服务端查处理耗时 <a class="header-anchor" href="#_1-3-第二步-回服务端查处理耗时" aria-label="Permalink to &quot;1.3 第二步：回服务端查处理耗时&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 服务端日志看该笔请求的处理时间（示例字段）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;risk-eval&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> risk.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;traceId=abc&quot;</span></span></code></pre></div><p data-src-line="36" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">日志显示单笔风控计算耗时 2.8 秒，且高峰时线程池排队。根因是风控模型在一次规则变更后引入了慢路径，不是网络。把 <code>read timed out</code> 当成网络故障，会让网络组在抓包上浪费时间。</p><h3 id="_1-4-根因与修复" tabindex="-1" data-src-line="38" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">1.4 根因与修复 <a class="header-anchor" href="#_1-4-根因与修复" aria-label="Permalink to &quot;1.4 根因与修复&quot;">​</a></h3><p data-src-line="40" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">根因是对端应用处理慢导致读超时。修复是回滚规则变更并给风控线程池扩容。教训：read 超时先看「请求 ACK 之后响应之前的间隔」，那段耗时在对端而不是网络上。</p><h2 id="case-2" tabindex="-1" data-src-line="42" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">案例二：重传与高 RTT 导致的延迟 <a class="header-anchor" href="#case-2" aria-label="Permalink to &quot;案例二：重传与高 RTT 导致的延迟 {#case-2}&quot;">​</a></h2><h3 id="_2-1-事故背景" tabindex="-1" data-src-line="44" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">2.1 事故背景 <a class="header-anchor" href="#_2-1-事故背景" aria-label="Permalink to &quot;2.1 事故背景&quot;">​</a></h3><p data-src-line="46" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">某跨地域调用整体 RT 偏高且抖动大，但应用处理日志显示本地处理只有十几毫秒。</p><h3 id="_2-2-第一步-看-rtt-与重传" tabindex="-1" data-src-line="48" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">2.2 第一步：看 RTT 与重传 <a class="header-anchor" href="#_2-2-第一步-看-rtt-与重传" aria-label="Permalink to &quot;2.2 第一步：看 RTT 与重传&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 按连接看 RTT 与拥塞窗口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tni</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.9.8.7</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ESTAB  0   0  10.0.1.1:8080   10.9.8.7:51000</span></span>
<span class="line"><span>        cubic ... rtt:180/40 rto:400 cwnd:3 ssthresh:2</span></span></code></pre></div><p data-src-line="60" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">RTT 180ms 且 <code>cwnd</code> 只有 3 个 MSS，<code>ssthresh</code> 降到 2，这是典型的发生过丢包后拥塞窗口被压小的状态。再确认重传：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Wireshark 过滤重传</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcp.analysis.retransmission</span></span></code></pre></div><p data-src-line="67" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">存在明显重传，说明链路质量差导致窗口长期偏小，每次传输的有效吞吐被拖低，累积成高 RT。</p><h3 id="_2-3-第二步-确认是链路问题还是路由绕行" tabindex="-1" data-src-line="69" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">2.3 第二步：确认是链路问题还是路由绕行 <a class="header-anchor" href="#_2-3-第二步-确认是链路问题还是路由绕行" aria-label="Permalink to &quot;2.3 第二步：确认是链路问题还是路由绕行&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">traceroute</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.9.8.7</span></span></code></pre></div><p data-src-line="75" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">路径跳数比预期多出一倍，存在绕行节点。根因是跨地域专线切换后路由走了公网绕行，丢包抬高了 RTT 和重传，不是应用慢。</p><h3 id="_2-4-根因与修复" tabindex="-1" data-src-line="77" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">2.4 根因与修复 <a class="header-anchor" href="#_2-4-根因与修复" aria-label="Permalink to &quot;2.4 根因与修复&quot;">​</a></h3><p data-src-line="79" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">根因是网络路径质量，修复是纠正路由回到专线。这个案例说明「应用处理快但 RT 高」要先看 <code>ss -tni</code> 的 RTT/cwnd，再决定是查链路还是查代码。</p><h2 id="case-3" tabindex="-1" data-src-line="81" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">案例三：应用侧消费不及时伪装成网络延迟 <a class="header-anchor" href="#case-3" aria-label="Permalink to &quot;案例三：应用侧消费不及时伪装成网络延迟 {#case-3}&quot;">​</a></h2><h3 id="_3-1-事故背景" tabindex="-1" data-src-line="83" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">3.1 事故背景 <a class="header-anchor" href="#_3-1-事故背景" aria-label="Permalink to &quot;3.1 事故背景&quot;">​</a></h3><p data-src-line="85" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">某长连接网关偶发上行数据延迟，客户端显示已发出，服务端处理却晚了数秒。</p><h3 id="_3-2-第一步-看-recv-q-是否堆积" tabindex="-1" data-src-line="87" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">3.2 第一步：看 Recv-Q 是否堆积 <a class="header-anchor" href="#_3-2-第一步-看-recv-q-是否堆积" aria-label="Permalink to &quot;3.2 第一步：看 Recv-Q 是否堆积&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tni</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0.2.9</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ESTAB  51200   0  10.0.1.1:9000   10.0.2.9:43000</span></span>
<span class="line"><span>                  ↑ Recv-Q 持续 50KB 以上</span></span></code></pre></div><p data-src-line="98" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"><code>Recv-Q</code> 持续偏高，表示数据已到达内核 socket 缓冲区但应用没有及时 <code>read()</code>。这不是网络延迟，而是应用消费慢，数据卡在内核缓冲里。</p><h3 id="_3-3-第二步-回线程栈看读线程" tabindex="-1" data-src-line="100" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">3.3 第二步：回线程栈看读线程 <a class="header-anchor" href="#_3-3-第二步-回线程栈看读线程" aria-label="Permalink to &quot;3.3 第二步：回线程栈看读线程&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jstack</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;nio-event-loop&quot;</span></span></code></pre></div><p data-src-line="106" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">读线程大量时间花在别的处理逻辑上，读循环被阻塞。根因是事件循环里混入了耗时同步调用，TCP 层准时收包但应用没读。</p><h3 id="_3-4-根因与修复" tabindex="-1" data-src-line="108" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">3.4 根因与修复 <a class="header-anchor" href="#_3-4-根因与修复" aria-label="Permalink to &quot;3.4 根因与修复&quot;">​</a></h3><p data-src-line="110" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md">根因是事件循环被阻塞导致消费不及时，不是网络。修复是把耗时逻辑移出读线程。这个案例提醒：<code>Recv-Q</code> 持续堆积是「应用没读」而不是「网络慢」的直接信号。</p><blockquote data-src-line="112" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"><p data-src-line="112" data-src-file="java/06-diagnostics/03-network/chapter-03-cases-timeout-latency.md"><strong>上一页：</strong> <a href="./chapter-02-cases-connection-failures.html">连接失败与建立缓慢案例</a><strong>下一页：</strong> <a href="./chapter-04-cases-connection-leaks.html">连接泄漏与状态异常案例</a><strong>返回：</strong> <a href="./chapter-01-network-diagnostics.html">网络性能分析与故障排查</a></p></blockquote>`,42)])])}const g=s(n,[["render",c]]);export{k as __pageData,g as default};
